sys_script_include.script:
function CreateParcelPart(vParcel, nWeight, nHeight, nWidth, nLength)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var IsValidSysId = x_snc_devtools.IsValidSysId;

	var grParcel = GetParcelRecord(vParcel);
	if (IsValidRecord(grParcel) == false)
	{
		return false;
	}

	var grPart = new GlideRecord('x_snc_parcel_part');
	grPart.initialize();
	grPart.parcel = grParcel.sys_id;
	grPart.weight = GetIntegerValue(nWeight);
	grPart.height = GetIntegerValue(nHeight);
	grPart.width = GetIntegerValue(nWidth);
	grPart.length = GetIntegerValue(nLength);
	var strPartSysId = grPart.insert();

	if (IsValidSysId(strPartSysId) == false)
	{
		return false;
	}
	return grPart;
}
